<script setup lang="ts">
import {ArrowLeft,ArrowRight,BookOpen,Minus,Plus,X,Sun,Moon,Bookmark,Heart,Check,Maximize2,Minimize2,SquarePen,Volume2} from 'lucide-vue-next'
import type {LibraryBook} from '~/data/library/catalog'
import {splitBookPages,readingPageTitle} from '~/utils/library/navigation'
import {readingLineChunks,latestReadingBookmark,bookmarkText} from '~/utils/library/reading'
const props=defineProps<{book:LibraryBook;start?:'beginning'|'bookmark'|'resume';position?:{page:number;line:number};listen?:boolean}>(),emit=defineEmits<{close:[]}>()
const {library,toggleBook}=useProgress()
const {records,storageNotice,load,migrateVerse,hydrateExcerpts,savePage,saveBookmark,removeBookmark}=useLibraryReading()
const expanded=ref(false),touchLine=ref(-1),resumeLine=ref(-1),tailSpace=ref(0)
const audioOpen=ref(Boolean(props.listen))
const selectedLine=ref(0),showContents=ref(false)
const isVerse=computed(()=>props.book.topic==='verse')
const isPoetry=computed(()=>isVerse.value||props.book.topic==='poetry')
const contents=computed(()=>pages.value.map((text,index)=>({title:readingPageTitle(text,index),index})))
const noteTarget=ref<{page:number;line:number}|null>(null),noteInput=ref<HTMLTextAreaElement>()
const notePosition=computed(()=>noteTarget.value||{page:page.value,line:selectedLine.value})
const editingMark=computed(()=>marks.value.find(mark=>mark.page===notePosition.value.page&&(mark.line??0)===notePosition.value.line))
const note=ref(''),showBookmarks=ref(false),bookmarkNotice=ref('')
const marks=computed(()=>records.value[props.book.id]?.bookmarks||[])
const currentMark=computed(()=>marks.value.find(mark=>mark.page===page.value&&(mark.line??0)===selectedLine.value))
const dialog=ref<HTMLDialogElement>(),body=ref<HTMLElement>(),loading=ref(true),error=ref(''),pages=ref<string[]>([]),page=ref(0),fontSize=ref(19),paper=ref(false)
const controller=new AbortController()
const lines=computed(()=>(pages.value[page.value]||'').split('\n'))
const textChunks=computed(()=>readingLineChunks(pages.value[page.value]||''))
const pageMarks=computed(()=>new Set(marks.value.filter(mark=>mark.page===page.value).map(mark=>mark.line??0)))
async function scrollToLine(line:number){
 await nextTick()
 if(document.fonts?.status==='loading')await document.fonts.ready
 const container=body.value
 if(!container)return
 tailSpace.value=line>0?Math.max(0,container.clientHeight-48):0
 await nextTick()
 const target=container.querySelector<HTMLElement>(`[data-line="${line}"]`)
 if(target)container.scrollTop=Math.max(0,container.scrollTop+target.getBoundingClientRect().top-container.getBoundingClientRect().top-16)
}
async function toggleContents(){preserveNote();noteTarget.value=null;note.value=currentMark.value?.note||'';showBookmarks.value=false;showContents.value=!showContents.value;await nextTick();if(showContents.value)resetPanelScroll();else await scrollToLine(selectedLine.value)}
function resetPanelScroll(){tailSpace.value=0;body.value?.scrollTo({top:0})}
async function toggleBookmarks(){
 preserveNote();showContents.value=false;showBookmarks.value=!showBookmarks.value
 if(showBookmarks.value){const mark=currentMark.value||marks.value[0];noteTarget.value=mark?{page:mark.page,line:mark.line??0}:{page:page.value,line:selectedLine.value};note.value=editingMark.value?.note||''}
 else{noteTarget.value=null;note.value=currentMark.value?.note||''}
 bookmarkNotice.value='';await nextTick();if(showBookmarks.value)resetPanelScroll();else await scrollToLine(selectedLine.value)
}
async function editBookmark(markPage:number,line=0){
 preserveNote();noteTarget.value={page:markPage,line};note.value=editingMark.value?.note||'';bookmarkNotice.value=''
 await nextTick();resetPanelScroll();noteInput.value?.focus({preventScroll:true})
}
function saveNote(){if(!note.value.trim())return;saveBookmark(props.book.id,notePosition.value.page,note.value,notePosition.value.line,bookmarkText(pages.value,notePosition.value.page,notePosition.value.line));bookmarkNotice.value='Նշումը պահպանված է։'}
function bookmarkExcerpt(markPage:number,line=0){return bookmarkText(pages.value,markPage,line)||'Պահպանված հատված'}
function markLine(line:number){
 preserveNote();selectedLine.value=line;resumeLine.value=line;savePage(props.book.id,page.value,line)
 const existing=marks.value.find(mark=>mark.page===page.value&&(mark.line??0)===line)
 if(existing){deleteMark(page.value,line);bookmarkNotice.value='Էջանշանը հանված է։';return}
 note.value='';saveBookmark(props.book.id,page.value,'',line,bookmarkExcerpt(page.value,line));bookmarkNotice.value='Տողը պահպանված է։'
}
function deleteMark(markPage:number,line=0){removeBookmark(props.book.id,markPage,line);if(markPage===notePosition.value.page&&line===notePosition.value.line)note.value=''}
function preserveNote(){if(!loading.value&&!error.value&&note.value.trim()&&note.value.trim()!==(editingMark.value?.note||''))saveBookmark(props.book.id,notePosition.value.page,note.value,notePosition.value.line,bookmarkText(pages.value,notePosition.value.page,notePosition.value.line))}
function go(value:number,line=0,highlight=false){preserveNote();noteTarget.value=null;touchLine.value=-1;showContents.value=false;showBookmarks.value=false;page.value=Math.max(0,Math.min(pages.value.length-1,value));selectedLine.value=Math.max(0,Math.min(line,lines.value.length-1));savePage(props.book.id,page.value,selectedLine.value);note.value=currentMark.value?.note||'';bookmarkNotice.value='';resumeLine.value=highlight?selectedLine.value:-1;void scrollToLine(selectedLine.value)}
onMounted(async()=>{
 paper.value=document.documentElement.classList.contains('factum-light');load(props.book.id);dialog.value?.showModal()
 try{
  const full=await $fetch<string>(props.book.file,{responseType:'text',signal:controller.signal})
  const start=full.match(/\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG EBOOK[^\n]*\*\*\*/i)
  const content=start?full.slice((start.index||0)+start[0].length).split(/\*\*\* END OF (?:THE|THIS) PROJECT GUTENBERG EBOOK/i)[0]!:full
  if(isPoetry.value)migrateVerse(props.book.id,content.trim(),props.book.topic)
  pages.value=splitBookPages(content.trim(),props.book.topic,4400)
  hydrateExcerpts(props.book.id,pages.value)
  const saved=records.value[props.book.id]
  const position=props.start==='beginning'?undefined:props.start==='bookmark'?(props.position||latestReadingBookmark(saved)):saved
  showContents.value=isVerse.value&&props.start!=='bookmark'&&(props.start==='beginning'||!saved?.updatedAt)
  page.value=Math.min(position?.page||0,pages.value.length-1);selectedLine.value=Math.min(position?.line||0,lines.value.length-1);note.value=currentMark.value?.note||'';savePage(props.book.id,page.value,selectedLine.value);if(isPoetry.value&&!records.value[props.book.id]?.pagination)migrateVerse(props.book.id,content.trim(),props.book.topic)
 }catch(e){if(!controller.signal.aborted)error.value='Գիրքը չհաջողվեց բեռնել։ Փակիր և փորձիր կրկին։'}finally{loading.value=false;resumeLine.value=props.start==='beginning'?-1:selectedLine.value;void scrollToLine(selectedLine.value)}
})
onUnmounted(()=>{preserveNote();controller.abort();dialog.value?.close()})
function keyboard(e:KeyboardEvent){if(showContents.value||showBookmarks.value||loading.value||error.value)return;if(['SELECT','INPUT','TEXTAREA'].includes((e.target as HTMLElement).tagName))return;if(e.key==='ArrowRight'){e.preventDefault();go(page.value+1)}if(e.key==='ArrowLeft'){e.preventDefault();go(page.value-1)}}
</script>
<template>
 <dialog ref="dialog" class="book-reader" :class="{paper,expanded}" aria-labelledby="reader-title" @cancel.prevent="emit('close')" @keydown="keyboard" @click="($event.target===dialog)&&emit('close')">
  <header><div><small>COGNITIO · ԸՆԹԵՐՑԱՍՐԱՀ</small><h2 id="reader-title">{{book.title}}</h2><p>{{book.author}} · {{book.language}}</p></div><div class="reader-window-actions"><button type="button" :aria-label="expanded?'Վերադառնալ պատուհանին':'Ամբողջ էջով կարդալ'" :aria-pressed="expanded" @click="expanded=!expanded"><Minimize2 v-if="expanded" :size="20"/><Maximize2 v-else :size="20"/></button><button type="button" aria-label="Փակել գիրքը" @click="emit('close')"><X :size="21"/></button></div></header>
  <nav class="reader-tools" aria-label="Ընթերցման կարգավորումներ"><span><BookOpen :size="15"/>Հայերեն ամբողջական բնագիր</span><div><button type="button" :disabled="fontSize<=16" aria-label="Փոքրացնել տառերը" @click="fontSize=Math.max(16,fontSize-1)"><Minus :size="16"/></button><span>{{fontSize}}</span><button type="button" :disabled="fontSize>=28" aria-label="Մեծացնել տառերը" @click="fontSize=Math.min(28,fontSize+1)"><Plus :size="16"/></button><button type="button" :aria-label="paper?'Մուգ ընթերցման ֆոն':'Բաց ընթերցման ֆոն'" @click="paper=!paper"><Moon v-if="paper" :size="17"/><Sun v-else :size="17"/></button></div></nav>
  <div class="reader-personal-tools"><button type="button" class="save-control" :aria-pressed="library.includes(book.id)" @click="toggleBook(book.id)"><Heart :size="15" :fill="library.includes(book.id)?'currentColor':'none'"/>{{library.includes(book.id)?'Պահպանված է':'Պահպանել գիրքը'}}</button><button type="button" :aria-expanded="audioOpen" @click="audioOpen=!audioOpen"><Volume2 :size="15"/>{{audioOpen?'Փակել լսումը':'Լսել գիրքը'}}</button><button type="button" :aria-expanded="showBookmarks" @click="toggleBookmarks"><Bookmark :size="15"/>Էջանշաններ · {{marks.length}}</button><button v-if="isVerse" type="button" :disabled="loading||!!error" :aria-expanded="showContents" @click="toggleContents"><BookOpen :size="15"/>Բանաստեղծություններ · {{pages.length}}</button><span v-if="currentMark"><Check :size="13"/>Էջանշված տող</span></div>
  <LazyLibraryBookAudioPlayer v-if="audioOpen" :book-id="book.id"/>

  <div ref="body" class="reader-body" :style="{fontSize:fontSize+'px'}" lang="hy" tabindex="0"><p v-if="loading" class="reader-status">Բեռնվում է միայն ընտրված գիրքը…</p><p v-else-if="error" role="alert" class="reader-status">{{error}}</p><section v-else-if="showBookmarks" class="reader-bookmarks" aria-label="Գրքի էջանշաններն ու նշումները"><div class="bookmarks-heading"><div><h3>Իմ էջանշանները</h3><p>{{marks.length}} պահպանված հատված</p></div><button type="button" @click="toggleBookmarks"><ArrowLeft :size="16"/>Վերադառնալ ընթերցմանը</button></div><div class="bookmark-editor"><label>Քո նշումը<textarea ref="noteInput" v-model="note" maxlength="1000" rows="2" placeholder="Ինչի՞ն ես ուզում վերադառնալ…"/></label><button type="button" :disabled="loading||!note.trim()" @click="saveNote"><Bookmark :size="14"/>Պահպանել նշումը</button><span role="status">{{bookmarkNotice}}</span></div><div class="bookmark-list"><p v-if="!marks.length">Այս գրքում դեռ էջանշան չկա։</p><div v-for="mark in marks" :key="mark.page+':'+(mark.line??0)" :class="{'selected-bookmark':notePosition.page===mark.page&&notePosition.line===(mark.line??0)}"><button type="button" @click="go(mark.page,mark.line??0,true)"><strong>{{isPoetry?(isVerse?readingPageTitle(pages[mark.page]||'',mark.page):book.title):'Էջ '+(mark.page+1)}}</strong><span class="bookmark-excerpt">{{bookmarkExcerpt(mark.page,mark.line??0)}}</span><span v-if="mark.note" class="bookmark-note">{{mark.note}}</span></button><div class="bookmark-actions"><button type="button" class="bookmark-edit" :aria-pressed="notePosition.page===mark.page&&notePosition.line===(mark.line??0)" @click="editBookmark(mark.page,mark.line??0)"><SquarePen :size="14"/>{{mark.note?'Խմբագրել նշումը':'Նշում գրել'}}</button><button type="button" :aria-label="'Հեռացնել էջանշանը․ '+bookmarkExcerpt(mark.page,mark.line??0)" @click="deleteMark(mark.page,mark.line??0)"><X :size="14"/></button></div></div></div></section><section v-else-if="showContents" class="poem-contents" aria-label="Բանաստեղծությունների ցանկ"><h3>Ընտրիր բանաստեղծությունը</h3><p>{{contents.length}} բանաստեղծություն · յուրաքանչյուրն առանձին էջում</p><ol><li v-for="item in contents" :key="item.index"><button type="button" :aria-current="item.index===page?'page':undefined" @click="go(item.index)"><span>{{item.index+1}}</span><strong>{{item.title}}</strong><ArrowRight :size="16"/></button></li></ol></section><div v-else class="reading-text"><LibraryReadingChunk v-for="(chunk,index) in textChunks" :key="page+':'+index" :lines="chunk" :marks="pageMarks" :touch-line="touchLine" :resume-line="resumeLine" @touch-line="touchLine=$event" @bookmark="markLine"/></div><div v-if="tailSpace&&!showBookmarks&&!showContents" aria-hidden="true" :style="{height:tailSpace+'px',flexShrink:0}"/></div>
  <footer><div v-if="!showContents&&!showBookmarks&&pages.length>1" class="reader-pagination"><button type="button" :disabled="loading||page===0" @click="go(page-1)"><ArrowLeft :size="16"/>Նախորդ</button><label>{{isVerse?'Բանաստեղծություն':'Էջ'}} <select :value="page" :disabled="loading" aria-label="Ընտրել ընթերցման էջը" @change="go(Number(($event.target as HTMLSelectElement).value))"><option v-for="(_,i) in pages" :key="i" :value="i">{{i+1}}</option></select> / {{pages.length||'…'}}</label><button type="button" :disabled="loading||page>=pages.length-1" @click="go(page+1)">Հաջորդ<ArrowRight :size="16"/></button></div><p v-if="storageNotice" role="status">Բրաուզերը չի թույլատրում պահպանել․ նշումները հիմա հասանելի են միայն այս բացված էջում։</p><p v-else>Ընթերցման տեղը և էջանշանները պահպանվում են այս սարքում։</p></footer>
 </dialog>
</template>
<style scoped>
.reader-body{isolation:isolate;contain:layout style;scrollbar-gutter:stable;scroll-behavior:auto;transform:translateZ(0)}

.poem-contents h3{font-size:20px;color:var(--reader-text);margin-bottom:8px}.poem-contents>p{font-size:11px;color:var(--reader-muted);margin-bottom:24px}.poem-contents ol{list-style:none;padding:0;margin:0;display:grid;gap:8px}.poem-contents li button{display:flex;align-items:center;gap:14px;width:100%;padding:14px 12px;border:1px solid var(--reader-line);border-radius:9px;text-align:left;font-size:14px;transition:background .15s}.poem-contents li button:hover,.poem-contents li button[aria-current]{background:#bc9c6115;border-color:#bc9c6170}.poem-contents li button>span{font-size:11px;color:#bc9c61;min-width:22px}.poem-contents strong{flex:1;font-weight:500}.poem-contents svg{flex-shrink:0;color:var(--reader-muted)}

.reader-body{scroll-padding-top:24px}

.reader-personal-tools{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:10px 28px;border-bottom:1px solid var(--reader-line)}.reader-personal-tools button,.reader-personal-tools>span{display:flex;align-items:center;gap:7px;font-size:10px;color:#c4a774}.reader-personal-tools button{border:1px solid var(--reader-line);border-radius:8px;padding:8px 11px}.reader-personal-tools button[aria-pressed=true]{background:#d6b87b15;color:#e2bb77}.reader-bookmarks{display:grid;grid-template-columns:minmax(200px,1fr) minmax(0,1.6fr);align-items:start;gap:24px;font-size:13px;line-height:1.7}.bookmarks-heading{grid-column:1/-1;display:flex;justify-content:space-between;align-items:center;gap:16px;padding-bottom:18px;border-bottom:1px solid var(--reader-line)}.bookmarks-heading h3{font-size:20px;font-weight:600}.bookmarks-heading p{font-size:12px;color:var(--reader-muted);margin-top:6px}.bookmarks-heading>button{display:flex;align-items:center;gap:8px;font-size:12px;color:#bc9c61}.bookmark-editor label{display:grid;gap:12px;color:var(--reader-muted)}.bookmark-editor textarea{width:100%;height:140px;min-height:140px;max-height:180px;background:var(--reader-bg);color:var(--reader-text);border:1px solid var(--reader-line);border-radius:9px;padding:12px;font:inherit;resize:vertical;overflow-y:auto}.bookmark-editor>button{display:inline-flex;width:fit-content;max-width:100%;align-items:center;gap:8px;padding:12px;margin-top:12px;color:#bc9c61;border:1px solid var(--reader-line);border-radius:9px}.bookmark-editor>span{display:block;margin-top:10px;color:var(--reader-muted);font-size:12px}.bookmark-list{min-width:0;display:grid;gap:12px}.bookmark-list>div{display:flex;align-items:flex-start;gap:10px;border:1px solid var(--reader-line);border-radius:10px;padding:14px;background:#bc9c6108}.bookmark-list>div>button:first-child{text-align:left;display:grid;gap:10px;min-width:0;flex:1}.bookmark-list strong{color:#bc9c61;font-size:12px;font-weight:500}.bookmark-list span{color:var(--reader-text);white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.8}.bookmark-list .bookmark-note{color:var(--reader-muted);font-size:12px;border-top:1px solid var(--reader-line);padding-top:8px}.bookmark-excerpt{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.bookmark-actions>button:last-child{padding:8px;border-radius:6px;color:var(--reader-muted);flex-shrink:0}.bookmark-actions>button:last-child:hover{background:#c66a5b20;color:#d58c7b}.bookmark-list>p{color:var(--reader-muted);line-height:1.8;padding:16px}.reader-body:has(>.reader-bookmarks){padding:24px 28px}.reader-personal-tools button[aria-expanded=true]{background:#d6b87b15;color:#e2bb77}@media(max-width:600px){.reader-personal-tools{padding:9px 15px}.reader-bookmarks{grid-template-columns:minmax(0,1fr);gap:20px}.reader-body:has(>.reader-bookmarks){padding:20px 16px}.bookmarks-heading{align-items:flex-start;flex-direction:column}.bookmarks-heading h3{font-size:18px}.bookmark-editor textarea{height:100px;min-height:100px;max-height:140px}.reader-personal-tools button{font-size:9px}}


.book-reader{--reader-bg:#111f30;--reader-text:#d9e0e8;--reader-line:#8395aa35;--reader-muted:#a1afbc;position:fixed;inset:0;margin:auto;width:min(960px,calc(100vw - 28px));height:min(900px,calc(100dvh - 36px));max-height:calc(100dvh - 36px);padding:0;border:1px solid #c4a96c70;border-radius:18px;background:var(--reader-bg);color:var(--reader-text);box-shadow:0 30px 100px #0008;overflow:hidden}.book-reader[open]{display:flex;flex-direction:column}.book-reader::backdrop{background:#020a16ed}.book-reader.paper{--reader-bg:#f5efdf;--reader-text:#352f27;--reader-line:#5e4c2a33;--reader-muted:#786c59}.book-reader header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;padding:23px 30px 19px;border-bottom:1px solid var(--reader-line)}header small{font-size:8px;letter-spacing:2px;color:var(--reader-muted)}header h2{font-size:21px;font-weight:600;line-height:1.6;margin:5px 0}header p{font-size:10px;color:var(--reader-muted)}header button{padding:7px}.reader-tools{display:flex;justify-content:space-between;gap:15px;align-items:center;padding:12px 30px;border-bottom:1px solid var(--reader-line);font-size:10px;color:var(--reader-muted)}.reader-tools>span,.reader-tools>div{display:flex;gap:13px;align-items:center}.reader-tools button{padding:5px}.reader-body{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:36px max(32px,8%);line-height:1.85;font-family:'Noto Sans Armenian',sans-serif}.reading-paragraph{white-space:pre-wrap;margin-bottom:1.15em;overflow-wrap:anywhere}.reader-status{font:13px 'Noto Sans Armenian',sans-serif;text-align:center;padding:50px 0;color:var(--reader-muted)}footer{padding:14px 28px;border-top:1px solid var(--reader-line)}.reader-pagination{display:flex;justify-content:space-between;align-items:center;gap:15px;font-size:11px}.reader-pagination button{display:flex;align-items:center;gap:8px;padding:7px}.reader-pagination label{display:flex;align-items:center;gap:7px;color:var(--reader-muted)}.reader-pagination select{background:var(--reader-bg);border:1px solid var(--reader-line);border-radius:5px;padding:5px;color:var(--reader-text)}footer>p{font-size:8px;line-height:1.8;color:var(--reader-muted);margin-top:9px;text-align:center}footer a{text-decoration:underline}button:disabled{opacity:.3}button:focus-visible,select:focus-visible,.reader-body:focus-visible{outline:2px solid #d9bd87;outline-offset:-2px}@media(max-width:600px){.book-reader{width:calc(100vw - 14px);height:calc(100dvh - 16px);max-height:calc(100dvh - 16px);border-radius:11px}.book-reader header{padding:17px 18px 14px}header h2{font-size:17px}.reader-tools{padding:9px 15px;font-size:8px}.reader-tools>span{max-width:160px;line-height:1.6}.reader-body{padding:25px 21px}footer{padding:10px 12px}.reader-pagination{font-size:9px;gap:4px}footer>p{font-size:7px}}
.reader-window-actions{display:flex;align-items:center;gap:8px;flex-shrink:0}.reader-window-actions button{display:grid;place-items:center;min-width:36px;min-height:36px;border:1px solid var(--reader-line);border-radius:8px}.reader-window-actions button:hover{background:#bc9c6115}.book-reader.expanded{width:100vw;max-width:100vw;height:100dvh;max-height:100dvh;border:0;border-radius:0}.book-reader.expanded .reader-body:not(:has(>.reader-bookmarks)){padding-left:max(24px,calc((100% - 1000px)/2));padding-right:max(24px,calc((100% - 1000px)/2))}
.bookmark-actions{display:flex;flex-direction:column;align-items:flex-end;gap:8px;flex-shrink:0}.bookmark-edit{display:flex;align-items:center;justify-content:center;gap:6px;padding:8px;border:1px solid var(--reader-line);border-radius:7px;color:#bc9c61;font-size:11px}.bookmark-edit[aria-pressed=true],.bookmark-edit:hover{border-color:#bc9c6180;background:#bc9c6112}.bookmark-list>div.selected-bookmark{border-color:#bc9c6180;background:#bc9c6112}.bookmark-editor textarea:focus{border-color:#d9bd87;outline:none;box-shadow:0 0 12px #d9bd871c}@media(max-width:600px){.bookmark-list>div{flex-wrap:wrap}.bookmark-list>div>button:first-child{flex-basis:100%}.bookmark-actions{width:100%;flex-direction:row;justify-content:space-between;align-items:center}.bookmark-edit{padding:10px 12px}}
.bookmark-list>div{transition:border-color .16s ease,background-color .16s ease}@media(hover:hover) and (pointer:fine){.bookmark-list>div:hover{border-color:#d9bd87;background:#bc9c6112}}@media(prefers-reduced-motion:reduce){.bookmark-list>div{transition:none}}
